import React from "react";
import { createRoot } from "react-dom/client";
import { DynamicSolution } from "./solution";

const elem = document.getElementById("bumblebee-solution-root");
if (elem) {
  const root = createRoot(elem);
  root.render(<DynamicSolution />);
} else {
  console.error(
    "Could not mount App because #cumbersome-solution-root was nowhere to be found",
  );
}
