export const DynamicSolution = () => {
  const [isExpanded, setIsExpanded] = useState(false);
  return (
    <>
      <p>
        This puzzle features a conlang from a world where sentient bees write
        down their{" "}
        <a href="https://en.wikipedia.org/wiki/Waggle_dance">communications</a>{" "}
        using glyphs on hexagons. Solvers are expected to slowly learn the
        grammar and some useful words from the Bee language via example
        sentences and eventually understand and even write their own complex
        sentences.
      </p>
      <p>
        This solution provides a lot of information for comprehensiveness. The
        reader may find certain sections more useful:
      </p>
      <ul className="list-disc list-inside">
        <li>
          {`The Level Layout section gives a runthrough of the puzzle's
          presentation and terminology, but should not be needed for anyone who
          has spent more than a few minutes looking through the puzzle.`}
        </li>
        <li>
          (<b>Recommended</b>) The Language Primer section will provide a
          crash-course to how the language works - after reading this (and
          importing the Full Lexicon), most of the sentences in the level should
          be understandable to some degree.
        </li>
        <li>
          The Advanced Grammar section covers the remaining grammar points, each
          of which are used in only some levels and/or not essential to the
          meaning of the sentences that they are used in.
        </li>
        <li>
          Intended solve paths for each individual level have also been
          provided. Each level is labeled with a letter for ease of reference,
          as well their complexity tier number, with T1 being the easiest and T3
          being the hardest. Lower tier levels provide many more examples and
          simpler grammar. This puzzle has been laid out so that levels require
          knowledge from earlier tiered levels, but none from levels in the same
          or higher tier. The solutions for each level will thus be presented as
          if the solver has not solved any other level of the same or higher
          tier.
        </li>
        <li>
          Full Lexicon contains the glosses for every word that appears in the
          puzzle and a list of all the semantic groups.
        </li>
      </ul>
      <div className="my-2 flex gap-2">
        <button
          className="rounded bg-yellow-700 p-2 text-white"
          onClick={() => {
            setIsExpanded(!isExpanded);
          }}
        >
          Expand/Collapse All
        </button>
      </div>
      {Sections.map((section, index) => (
        <SolutionSection
          key={index}
          section={section}
          isExpanded={isExpanded}
        />
      ))}
    </>
  );
};

type SolutionSectionData = {
  head: React.ReactNode;
  body: React.ReactNode;
};

type SolutionSectionProps = {
  section: SolutionSectionData;
  isExpanded: boolean;
};

const SolutionSection = (props: SolutionSectionProps) => {
  return (
    <details
      open={props.isExpanded}
      className="text-left my-4 rounded-md border-2 border-yellow-700 bg-yellow-200 open:mb-0
      open:bg-transparent [&_summary]:open:bg-yellow-300 [&_summary]:open:rounded-t-md
      [&_summary]:open:border-b-1 [&_summary]:open:border-yellow-700 [&_svg]:open:-rotate-180"
    >
      <summary className="select-none flex cursor-pointer list-none items-center text-center p-1">
        <div>
          <svg
            className="rotate-0 transform text-yellow-700 transition-all duration-300"
            fill="none"
            height="20"
            width="20"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="4"
            viewBox="0 0 24 24"
          >
            <polyline points="6 9 12 15 18 9"></polyline>
          </svg>
        </div>
        {props.section.head}
      </summary>
      <div className="p-2">{props.section.body}</div>
    </details>
  );
};

const imageContainer = (identifier: string, image_url: string) => {
  return imageContainerWithMaxHeight(identifier, image_url, 600);
};

const imageContainerWithMaxHeight = (
  identifier: string,
  image_url: string,
  maxHeight: number,
) => {
  return (
    <div className="flex justify-center my-4">
      <div className="items-center bg-yellow-100 p-2 rounded-md border border-yellow-300 w-fit">
        <h3>{identifier}</h3>
        <div className="p-1">
          <img
            src={image_url}
            alt={identifier}
            style={{ maxHeight: `${maxHeight}px` }}
          />
        </div>
      </div>
    </div>
  );
};

const renderExamples = (
  level_prefix: string,
  // With 1-based indexing
  startingIndex: number,
  examples: string[],
) => {
  return (
    <div className="grid grid-cols-1 my-4">
      {examples.map((example, index) => {
        const identifier = `Example ${level_prefix}${index + startingIndex}`;
        return imageContainer(identifier, example);
      })}
    </div>
  );
};

